#include <stdio.h>

void abort(void);
void exit(int);

#ifdef DEBUG
#define abort() printf("error, line %d\n", __LINE__)
#endif

int count;

void a1() { ++count; }

void b(unsigned char data) {
  if (data & 0x80)
    a1();
  data <<= 1;

  if (data & 0x80)
    a1();
  data <<= 1;

  if (data & 0x80)
    a1();
}

int main(void) {
  count = 0;
  b(0);
  if (count != 0)
    abort();

  count = 0;
  b(0x80);
  if (count != 1)
    abort();

  count = 0;
  b(0x40);
  if (count != 1)
    abort();

  count = 0;
  b(0x20);
  if (count != 1)
    abort();

  count = 0;
  b(0xc0);
  if (count != 2)
    abort();

  count = 0;
  b(0xa0);
  if (count != 2)
    abort();

  count = 0;
  b(0x60);
  if (count != 2)
    abort();

  count = 0;
  b(0xe0);
  if (count != 3)
    abort();

#ifdef DEBUG
  printf("Done.\n");
#endif
  exit(0);
}


